import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long numerator = sc.nextLong();
        long denominator = sc.nextLong();
        long max_iter = sc.nextLong();

        double ratio = (double) numerator / denominator;
        long a_candidate = 1;
        long b_candidate = 1;
        double min_diff = 1e9;
        double epsilon = 1e-25;

        if (denominator <= b_candidate) {
            System.out.println(numerator + "/" + denominator);
            sc.close();
            return;
        }

        for (long i = 1; i <= max_iter; i++) {
            double val = ratio * i;
            long a1 = (long) Math.floor(val);
            long a2 = (long) Math.ceil(val);

            double current_diff = Math.abs(ratio - (double) a1 / i);
            if (current_diff < min_diff - epsilon) {
                min_diff = current_diff;
                a_candidate = a1;
                b_candidate = i;
            }

            current_diff = Math.abs((double) a2 / i - ratio);
            if (current_diff < min_diff - epsilon) {
                min_diff = current_diff;
                a_candidate = a2;
                b_candidate = i;
            }
        }

        System.out.println(a_candidate + "/" + b_candidate);
        sc.close();
    }
}
